bool StructTraits<::brave_shields::mojom::SubscriptionInfo::DataView, ::brave_shields::mojom::SubscriptionInfoPtr>::Read(
    ::brave_shields::mojom::SubscriptionInfo::DataView input,
    ::brave_shields::mojom::SubscriptionInfoPtr* output) {
  bool success = true;
  ::brave_shields::mojom::SubscriptionInfoPtr result(::brave_shields::mojom::SubscriptionInfo::New());
  
      if (success)
        result->enabled = input.enabled();
      if (success && !input.ReadTitle(&result->title))
        success = false;
      if (success && !input.ReadHomepage(&result->homepage))
        success = false;
      if (success && !input.ReadLastUpdatedPrettyText(&result->last_updated_pretty_text))
        success = false;
      if (success && !input.ReadSubscriptionUrl(&result->subscription_url))
        success = false;
      if (success && !input.ReadLastUpdateAttempt(&result->last_update_attempt))
        success = false;
      if (success && !input.ReadLastSuccessfulUpdateAttempt(&result->last_successful_update_attempt))
        success = false;
      if (success)
        result->expires = input.expires();
  *output = std::move(result);
  return success;
}

